const nowyElement = document.createElement("li");
nowyElement.textContent = "Nauka DOM";
document.getElementById("task-list").appendChild(nowyElement);

const pierwszy = document.createElement("li");
pierwszy.textContent = "Pierwsze w kolejce";
document.getElementById("task-list").prepend(pierwszy);

const taskList = document.getElementById("task-list");
const firstTask = document.querySelector(".task");

const nowy = document.createElement("li");
nowy.textContent = "Wstawione przed";
taskList.insertBefore(nowy, firstTask);

document.getElementById("task-list").insertAdjacentHTML(
  "afterbegin",
  "<li class='task'>Wstawione przez HTML</li>"
);

const oryginal = document.getElementById("product-1");
const klon = oryginal.cloneNode(true);
klon.textContent = "Klon laptopa";
document.getElementById("product-container").appendChild(klon);

// container.innerHTML += nowyHtml odczytuje CALA istniejaca zawartosc,
// dokleja do niej nowyHtml, a nastepnie NA NOWO buduje CALY HTML od zera.
// Ten proces NISZCZY wszystkie event listenery (rozdzial 12) podpiete
// do istniejacych elementow wewnatrz kontenera, poniewaz sa one
// tworzone na nowo jako 'swiezuo' elementy.
//
// insertAdjacentHTML dodaje nowy HTML W KONKRETNYM miejscu, NIE
// dotykajac istniejacej zawartosci - istniejace elementy (i ich event
// listenery) pozostaja nienaruszone, a nowy HTML jest po prostu
// 'dolaczany' obok.

const akapit = document.createElement("p");
akapit.textContent = "Nowy akapit";
console.log(akapit.parentElement === null);

const zadanie = document.createElement("li");
zadanie.textContent = "Zadanie X";
document.getElementById("task-list").appendChild(zadanie);
console.log(zadanie.parentElement.id);

const drugi = document.createElement("li");
drugi.textContent = "Drugi";
const pierwszy = document.createElement("li");
