const gleboki = oryginal.cloneNode(true);
console.log(plytki.children.length, gleboki.children.length);

function dodajZadanie(tresc) {
  const zadanie = document.createElement("li");
  zadanie.textContent = tresc;
  document.getElementById("task-list").appendChild(zadanie);
}

dodajZadanie("Pierwsze");
dodajZadanie("Drugie");
console.log(document.getElementById("task-list").children.length);

// createElement tworzy nowy element WYLACZNIE "w pamieci" - element
// istnieje jako obiekt JavaScript, ale NIE jest jeszcze czescia drzewa
// DOM (jego parentElement to null). Przegladarka renderuje TYLKO to,
// co faktycznie znajduje sie w drzewie DOM - dopiero wywolanie
// appendChild/prepend/insertBefore "wpina" nowy element do drzewa,
// czyniac go widocznym. Bez tego kroku element pozostaje "w magazynie",
// nigdy nie trafiajac na widoczna strone.

const oryginal = { tag: "li", tekst: "Zadanie", dzieci: [{ tag: "span", tekst: "x" }] };
const klon = structuredClone(oryginal);
klon.dzieci[0].tekst = "y";
console.log(oryginal.dzieci[0].tekst, klon.dzieci[0].tekst);

function appendChildSym(rodzic, dziecko) {
  rodzic.dzieci.push(dziecko);
}

const rodzic = { dzieci: [] };
appendChildSym(rodzic, "a");
appendChildSym(rodzic, "b");
console.log(rodzic.dzieci);

function prependSym(rodzic, dziecko) {
  rodzic.dzieci.unshift(dziecko);
}

const rodzic = { dzieci: ["b", "c"] };
prependSym(rodzic, "a");
console.log(rodzic.dzieci);

function removeSym(tablica, wartosc) {
  const indeks = tablica.indexOf(wartosc);
  if (indeks !== -1) tablica.splice(indeks, 1);
  return tablica;
}

console.log(removeSym(["a", "b", "c"], "b"));

const kontener = document.getElementById("product-container");
const klon = kontener.firstElementChild.cloneNode(true);
klon.textContent = "Klon";
kontener.appendChild(klon);
console.log(kontener.children.length);

// element.innerHTML += nowyHtml odczytuje CALA istniejaca zawartosc,
// dokleja do niej nowyHtml, a NASTEPNIE buduje CALY HTML OD ZERA - niszczy
// to wszystkie event listenery podpiete do istniejacych elementow wewnatrz.
//
// element.insertAdjacentHTML(pozycja, nowyHtml) dodaje nowy HTML w
// konkretnym miejscu, NIE dotykajac istniejacej zawartosci - stare
// elementy (i ich listenery) pozostaja nienaruszone.

const lista = document.getElementById("task-list");
lista.insertAdjacentHTML("afterbegin", "<li>Poczatek</li>");
lista.insertAdjacentHTML("beforeend", "<li>Koniec</li>");
console.log(lista.firstElementChild.textContent, lista.lastElementChild.textContent);

function usunWszystkie(selektor) {
  document.querySelectorAll(selektor).forEach((el) => el.remove());
}

usunWszystkie(".task");

const pusty = document.createElement("li");
document.getElementById("task-list").appendChild(pusty);
console.log(pusty.textContent === "");

function zdupplikujElement(elementId) {
  return document.getElementById(elementId).cloneNode(true);
}

const klon = zdupplikujElement("product-1");
console.log(klon.parentElement === null);

function insertBeforeSym(tablica, nowyElement, referencyjny) {
  const indeks = tablica.indexOf(referencyjny);
  tablica.splice(indeks, 0, nowyElement);
  return tablica;
}

console.log(insertBeforeSym(["a", "c"], "b", "c"));

// createElement dziala jak zamowienie nowego mebla z fabryki - mebel
// juz istnieje, jest gotowy, ale stoi jeszcze w magazynie (pamieci),
// nie w zadnym pokoju (drzewie DOM).
// appendChild/prepend/insertBefore dzialaja jak faktyczne wstawienie
// mebla do konkretnego pokoju (elementu-rodzica) - dopiero wtedy mebel
// staje sie widoczny i czescia calego "mieszkania" (strony).

const kontener = document.getElementById("product-container");
const przed = kontener.children.length;
kontener.appendChild(kontener.firstElementChild.cloneNode(true));
const po = kontener.children.length;
console.log(po - przed);

